set -euo pipefail
cd /home/ubuntu/apps/travel-planner
.venv/bin/python - <<'PY'
import base64,json
from pathlib import Path
data=json.loads('{"rag/service/map_budget.py": "", "rag/service/trip_service.py": "", "rag/service/baidu_maps.py": "", "rag/service/retrieval_server.py": "", "rag/eval/tests/test_baidu_maps.py": "", "rag/eval/tests/test_trip_budget.py": "", "rag/client/run_on_server.ps1": ""}')
for n,b in data.items():
 p=Path(n);backup=Path('deploy/backups/trip-budget-v1')/n
 if p.exists() and not backup.exists():
  backup.parent.mkdir(parents=True,exist_ok=True);backup.write_bytes(p.read_bytes())
 p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(base64.b64decode(b))
PY
PYTHONPATH=rag .venv/bin/python -m unittest discover -s rag/eval/tests -p 'test_*.py'
